import type * as PageTree from 'fumadocs-core/page-tree';
import meta from '@/content/docs/examples/more/meta.json';
import { docsRoute } from './shared';

/**
 * The rows of the Examples sidebar's "More examples" folder (D103, D116).
 *
 * The 594 story pages each carried the folder's whole row list in their HTML
 * and RSC payload. The page tree the docs layout sends (lib/source.ts
 * `sidebarTree`) now holds the folder without its rows, and the browser
 * builds them from the folder's meta.json, generated by lib/story-pages.mjs
 * and shipped once in the docs JavaScript: its order, its "---Group---"
 * labels and the story slugs give every row's URL, group and number. A row's
 * label is its slug in title case ("aggregation-expanded-default" reads
 * "Aggregation Expanded Default"); the few labels that differ travel in the
 * folder node, and `sidebarTree` fails the build when the rows built here
 * differ from the folder `source` holds.
 */

/** URL prefix of every "More examples" row. */
export const MORE_EXAMPLES_URL = `${docsRoute}/examples/more/`;

/** The "More examples" folder as the docs layout sends it: no rows, the labels that differ from the slug. */
export type LightMoreExamples = PageTree.Folder & {
  moreLabels: Record<string, string>;
};

/** True for the "More examples" folder of the light tree. */
export function isLightMoreExamples(
  node: PageTree.Node,
): node is LightMoreExamples {
  return node.type === 'folder' && 'moreLabels' in node;
}

/** The label a row gets from its slug: the story part after "--", in title case. */
export function slugLabel(slug: string): string {
  const story = slug.slice(slug.indexOf('--') + 2);
  return story
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

/** The folder's rows, in meta.json order: a separator per group, then its pages. */
export function moreExamplesRows(
  labels: Record<string, string>,
): PageTree.Node[] {
  return meta.pages.map((entry): PageTree.Node => {
    const group = /^---(.*)---$/.exec(entry);
    if (group) return { type: 'separator', name: group[1] };
    const name = labels[entry] ?? slugLabel(entry);
    return { type: 'page', name, url: `${MORE_EXAMPLES_URL}${entry}` };
  });
}

const fullTrees = new WeakMap<PageTree.Root, PageTree.Root>();

/** The light tree with the "More examples" rows put back; the same object for the same tree. */
export function withMoreExamples(tree: PageTree.Root): PageTree.Root {
  let full = fullTrees.get(tree);
  if (full) return full;
  const fill = (node: PageTree.Node): PageTree.Node => {
    if (node.type !== 'folder') return node;
    if (isLightMoreExamples(node)) {
      const { moreLabels, ...folder } = node;
      return { ...folder, children: moreExamplesRows(moreLabels) };
    }
    return { ...node, children: node.children.map(fill) };
  };
  full = { ...tree, children: tree.children.map(fill) };
  fullTrees.set(tree, full);
  return full;
}
